def _zenrows_get(url: str, extra_headers: dict = None) -> requests.Response:
    """GET qua ZenRows với CF bypass."""
    params = {
        "apikey": ZENROWS_API_KEY,
        "url": url,
        "js_render": "false",
        "premium_proxy": "true",
    }
    h = {"Content-Type": "application/json"}
