# ─── Download nhạc ───────────────────────────────────────────
def search_audio(query: str, pick_random: bool = True) -> tuple[str, str]:
    """Chỉ tìm kiếm trên YouTube, trả về (url, title) mà KHÔNG tải file."""
    ydl_opts = {
        "quiet": True,
        "no_warnings": True,
        "noplaylist": True,
        "skip_download": True,
        "extract_flat": "in_playlist",
        "http_headers": {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
            "Accept-Language": "en-US,en;q=0.9",
        },
    }

    with yt_dlp.YoutubeDL(ydl_opts) as ydl:
        search_results = ydl.extract_info(f"ytsearch5:{query}", download=False)
        if search_results and "entries" in search_results:
            entries = [e for e in search_results["entries"] if e and e.get("id")]
            if entries:
                chosen = random.choice(entries[:5]) if pick_random else entries[0]
                video_id = chosen.get("id", "")
                url = f"https://www.youtube.com/watch?v={video_id}"
                title = chosen.get("title", query)
                return url, title
        raise Exception("Không tìm thấy kết quả trên YouTube")


def download_audio_soundcloud(query: str) -> tuple[str, str]:
    """Tải nhạc từ SoundCloud (dùng cho /randommusic2).
    
    Tìm ngẫu nhiên trong top 5 kết quả SoundCloud.
    """
    os.makedirs("/tmp", exist_ok=True)
    MAX_FILE_MB = 44

    ydl_opts = {
        "format": "bestaudio[abr<=128]/bestaudio/best",
        "max_filesize": MAX_FILE_MB * 1024 * 1024,
        "outtmpl": "/tmp/%(title)s.%(ext)s",
        "postprocessors": [{
            "key": "FFmpegExtractAudio",
            "preferredcodec": "mp3",
            "preferredquality": "96",
        }],
        "quiet": False,
        "no_warnings": False,
        "noplaylist": True,
        "ignoreerrors": True,
        "no_check_certificate": True,
        "socket_timeout": 30,
        "default_search": "scsearch5",  # Top 5 SoundCloud
    }

    with yt_dlp.YoutubeDL(ydl_opts) as ydl:
        # Tìm top 5 trước (extract_flat để nhanh)
        flat_opts = dict(ydl_opts)
        flat_opts["extract_flat"] = True
        flat_opts["skip_download"] = True
        flat_opts.pop("max_filesize", None)
        with yt_dlp.YoutubeDL(flat_opts) as ydl_flat:
            results = ydl_flat.extract_info(query, download=False)

        entries = []
        if results:
            if "entries" in results:
                entries = [e for e in results["entries"] if e and e.get("url")]
            elif results.get("url"):
                entries = [results]

        if not entries:
            raise Exception("Không tìm thấy kết quả trên SoundCloud")

        chosen = random.choice(entries[:5])
        track_url = chosen.get("url") or chosen.get("webpage_url", "")

        # Tải bài đã chọn
        info = ydl.extract_info(track_url, download=True)
        if info and "entries" in info:
            info = info["entries"][0]
        title = info.get("title", query) if info else query
        filepath = ydl.prepare_filename(info).rsplit(".", 1)[0] + ".mp3" if info else ""

        if filepath and os.path.exists(filepath):
            file_size_mb = os.path.getsize(filepath) / (1024 * 1024)
            if file_size_mb > MAX_FILE_MB:
                os.remove(filepath)
                raise Exception(f"File quá lớn ({file_size_mb:.1f} MB). Thử lại nhé!")
            return filepath, title

        raise Exception("Không tải được file từ SoundCloud")


def download_audio(query: str, pick_random: bool = False, pick_index: int = None) -> tuple[str, str]:
    """Tải nhạc từ YouTube hoặc SoundCloud.
    
    pick_random=True      → chọn ngẫu nhiên trong top 5 (dùng cho /randommusic)
    pick_index=N (1-5)    → chọn bài thứ N trong kết quả tìm kiếm
    pick_index=None       → chọn ngẫu nhiên trong top 3 (mặc định)
    
    Giới hạn file: 45MB để tránh lỗi 413 khi gửi qua Telegram.
    """
    os.makedirs("/tmp", exist_ok=True)
    
    MAX_FILE_MB = 44      # Telegram limit 50MB, buffer aman
    
    ydl_opts = {
        # Prioritaskan audio bitrate rendah dulu, max_filesize sebagai hard stop di yt-dlp level
        "format": "bestaudio[abr<=128][filesize<44M]/bestaudio[abr<=128]/bestaudio/best",
        "max_filesize": MAX_FILE_MB * 1024 * 1024,
        "outtmpl": "/tmp/%(title)s.%(ext)s",
        "postprocessors": [
            {
                "key": "FFmpegExtractAudio",
                "preferredcodec": "mp3",
                "preferredquality": "96",  # 128 → 96kbps: kualitas masih oke, file lebih kecil
            }
        ],
        "quiet": False,
        "no_warnings": False,
        "noplaylist": True,
        "ignoreerrors": True,
        "no_check_certificate": True,
        "prefer_insecure": True,
        "extract_flat": False,
        "force_generic_extractor": False,
        "geo_bypass": True,
        "socket_timeout": 30,
        # match_filter dihapus — tidak reliable saat download=True, ganti pre-check manual
    }

    try:
        print(f"🔍 Đang tìm trên YouTube: {query}")
        
        # Tìm kiếm top 5
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            search_results = ydl.extract_info(f"ytsearch5:{query}", download=False)
            
            if search_results and "entries" in search_results and search_results["entries"]:
                entries = [e for e in search_results["entries"] if e]
                
                if pick_index is not None:
                    # Chọn theo vị trí (1-based), clamp vào số kết quả thực
                    idx = max(0, min(pick_index - 1, len(entries) - 1))
                    chosen = entries[idx]
                    print(f"✅ Đã chọn bài #{pick_index} (idx={idx}): {chosen.get('title')}")
                elif pick_random:
                    # /randommusic → hoàn toàn ngẫu nhiên trong top 5
                    chosen = random.choice(entries[:5])
                    print(f"✅ Đã chọn ngẫu nhiên (top 5): {chosen.get('title')}")
                else:
                    # /music mặc định → ngẫu nhiên trong top 3
                    chosen = random.choice(entries[:3])
                    print(f"✅ Đã chọn ngẫu nhiên (top 3): {chosen.get('title')}")
                
                video_url = chosen["webpage_url"]
                video_title = chosen.get("title", "Không có tiêu đề")
                print(f"⏱ Duration: {chosen.get('duration', '?')}s")

                # Tải video đã chọn
                info = ydl.extract_info(video_url, download=True)
                title = info.get("title", query)
                filepath = ydl.prepare_filename(info).rsplit(".", 1)[0] + ".mp3"
                
                if os.path.exists(filepath):
                    # Kiểm tra kích thước file
                    file_size_mb = os.path.getsize(filepath) / (1024 * 1024)
                    print(f"📦 Kích thước file: {file_size_mb:.1f} MB")
                    if file_size_mb > MAX_FILE_MB:
                        os.remove(filepath)
                        raise Exception(f"File quá lớn ({file_size_mb:.1f} MB > {MAX_FILE_MB} MB). Hãy thử bài khác hoặc bài ngắn hơn!")
                    return filepath, title
                else:
                    raise Exception("Không tìm thấy file sau khi tải")
            else:
                raise Exception("Không tìm thấy kết quả trên YouTube")
            
    except Exception as e:
        print(f"❌ Lỗi YouTube: {str(e)}")
        
        # Thử tìm trên SoundCloud
        try:
            print(f"🔍 Đang tìm trên SoundCloud: {query}")
            sc_opts = dict(ydl_opts)
            sc_opts["default_search"] = "scsearch1"
            sc_opts.pop("match_filter", None)
            
            with yt_dlp.YoutubeDL(sc_opts) as ydl:
                info = ydl.extract_info(query, download=True)
                if "entries" in info:
                    info = info["entries"][0]
                title = info.get("title", query)
                filepath = ydl.prepare_filename(info).rsplit(".", 1)[0] + ".mp3"
                
                if os.path.exists(filepath):
                    file_size_mb = os.path.getsize(filepath) / (1024 * 1024)
                    if file_size_mb > MAX_FILE_MB:
                        os.remove(filepath)
                        raise Exception(f"File quá lớn ({file_size_mb:.1f} MB). Hãy thử bài khác!")
                    return filepath, title
                else:
                    raise Exception("Không tìm thấy file sau khi tải từ SoundCloud")
                    
        except Exception as e2:
            print(f"❌ Lỗi SoundCloud: {str(e2)}")
            raise Exception(f"Không thể tìm bài hát: {query}\nVui lòng thử lại với tên khác!")

# ─── Hàm lấy thời tiết hiện tại ─────────────────────────────
def get_current_weather(city: str) -> str:
    """Lấy thời tiết hiện tại"""
    try:
        # Tìm tọa độ từ tên thành phố
        geo_url = f"http://api.openweathermap.org/geo/1.0/direct?q={city}&limit=1&appid={OPENWEATHER_API_KEY}"
        geo_response = requests.get(geo_url, timeout=10)
        geo_data = geo_response.json()
        
        if not geo_data:
            return f"❌ Không tìm thấy thành phố '{city}'. Vui lòng thử lại với tên khác."
        
        lat = geo_data[0]['lat']
        lon = geo_data[0]['lon']
        
        # Lấy thời tiết hiện tại
        weather_url = f"https://api.openweathermap.org/data/2.5/weather?lat={lat}&lon={lon}&appid={OPENWEATHER_API_KEY}&units=metric&lang=vi"
        weather_response = requests.get(weather_url, timeout=10)
        weather_data = weather_response.json()
        
        if weather_response.status_code != 200:
            return f"❌ Lỗi API: {weather_data.get('message', 'Không xác định')}"
        
        # Lấy dữ liệu
        temp = round(weather_data['main']['temp'])
        feels_like = round(weather_data['main']['feels_like'])
        weather = weather_data['weather'][0]['main']
        weather_desc = weather_data['weather'][0]['description']
        humidity = weather_data['main']['humidity']
        wind_speed = round(weather_data['wind']['speed'] * 3.6, 1)
        pressure = weather_data['main']['pressure']
        
        # Chuyển đổi tên thành phố sang tiếng Việt
        city_names = {
            "hanoi": "Hà Nội",
            "ho chi minh": "Hồ Chí Minh",
            "danang": "Đà Nẵng",
            "haiphong": "Hải Phòng",
            "cantho": "Cần Thơ",
            "nhatrang": "Nha Trang",
            "dalat": "Đà Lạt",
            "vungtau": "Vũng Tàu",
            "hue": "Huế",
            "ha noi": "Hà Nội",
            "ho chi minh city": "Hồ Chí Minh",
            "da nang": "Đà Nẵng",
            "hai phong": "Hải Phòng",
            "can tho": "Cần Thơ",
            "nha trang": "Nha Trang",
            "da lat": "Đà Lạt",
            "vung tau": "Vũng Tàu",
        }
        city_name = city_names.get(city.lower(), city.title())
        
        # Xác định thời tiết và icon
        if weather.lower() in ['rain', 'drizzle', 'thunderstorm']:
            icon = "☔"
            advice = "📌 **Nhớ mang ô (dù) khi ra ngoài nhé!**"
        elif weather.lower() in ['clear']:
            icon = "☀️"
            advice = "📌 **Nhớ mặc áo chống nắng và bôi kem chống nắng nhé!**"
        elif weather.lower() in ['clouds']:
            icon = "☁️"
            advice = "📌 **Trời nhiều mây, mang áo khoác nhẹ phòng khi se lạnh.**"
        elif weather.lower() in ['snow']:
            icon = "❄️"
            advice = "📌 **Trời lạnh, nhớ mặc ấm và mang khăn choàng nhé!**"
        else:
            icon = "🌤️"
            advice = "📌 **Thời tiết khá ổn, vẫn nên chuẩn bị nhẹ nhàng nhé!**"
        
        # Tạo kết quả
        result = f"🌡️ *Thời tiết hiện tại tại {city_name}:*\n\n"
        result += f"{icon} Nhiệt độ: {temp}°C (cảm giác như {feels_like}°C)\n"
        result += f"📝 Mô tả: {weather_desc.capitalize()}\n"
        result += f"💧 Độ ẩm: {humidity}%\n"
        result += f"💨 Gió: {wind_speed} km/h\n"
        result += f"📊 Áp suất: {pressure} hPa\n"
        result += f"\n{advice}"
        
        return result
        
    except requests.exceptions.Timeout:
        return "❌ Kết nối API quá chậm. Vui lòng thử lại sau."
    except requests.exceptions.ConnectionError:
        return "❌ Không thể kết nối đến API. Vui lòng kiểm tra kết nối mạng."
    except Exception as e:
        return f"❌ Đã xảy ra lỗi: {str(e)}"

# ─── Hàm dự báo thời tiết ngày mai ─────────────────────────
def get_weather_forecast(city: str) -> str:
    """Lấy dự báo thời tiết ngày mai"""
    try:
        # Tìm tọa độ từ tên thành phố
        geo_url = f"http://api.openweathermap.org/geo/1.0/direct?q={city}&limit=1&appid={OPENWEATHER_API_KEY}"
        geo_response = requests.get(geo_url, timeout=10)
        geo_data = geo_response.json()
        
        if not geo_data:
            return f"❌ Không tìm thấy thành phố '{city}'. Vui lòng thử lại với tên khác."
        
        lat = geo_data[0]['lat']
        lon = geo_data[0]['lon']
        
        # Lấy dự báo 5 ngày
        forecast_url = f"https://api.openweathermap.org/data/2.5/forecast?lat={lat}&lon={lon}&appid={OPENWEATHER_API_KEY}&units=metric&lang=vi"
        forecast_response = requests.get(forecast_url, timeout=10)
        forecast_data = forecast_response.json()
        
        if forecast_response.status_code != 200:
            return f"❌ Lỗi API: {forecast_data.get('message', 'Không xác định')}"
        
        # Tìm dự báo ngày mai
        tomorrow = (datetime.now() + timedelta(days=1)).strftime('%Y-%m-%d')
        tomorrow_forecast = None
        
        for item in forecast_data['list']:
            if item['dt_txt'].startswith(tomorrow):
                tomorrow_forecast = item
                break
        
        if not tomorrow_forecast:
            return "❌ Không có dữ liệu dự báo cho ngày mai."
        
        # Lấy dữ liệu
        temp = round(tomorrow_forecast['main']['temp'])
        feels_like = round(tomorrow_forecast['main']['feels_like'])
        weather = tomorrow_forecast['weather'][0]['main']
        weather_desc = tomorrow_forecast['weather'][0]['description']
        humidity = tomorrow_forecast['main']['humidity']
        wind_speed = round(tomorrow_forecast['wind']['speed'] * 3.6, 1)
        rain_prob = tomorrow_forecast.get('pop', 0) * 100
        
        # Chuyển đổi tên thành phố sang tiếng Việt
        city_names = {
            "hanoi": "Hà Nội",
            "ho chi minh": "Hồ Chí Minh",
            "danang": "Đà Nẵng",
            "haiphong": "Hải Phòng",
            "cantho": "Cần Thơ",
            "nhatrang": "Nha Trang",
            "dalat": "Đà Lạt",
            "vungtau": "Vũng Tàu",
            "hue": "Huế",
            "ha noi": "Hà Nội",
            "ho chi minh city": "Hồ Chí Minh",
            "da nang": "Đà Nẵng",
            "hai phong": "Hải Phòng",
            "can tho": "Cần Thơ",
            "nha trang": "Nha Trang",
            "da lat": "Đà Lạt",
            "vung tau": "Vũng Tàu",
        }
        city_name = city_names.get(city.lower(), city.title())
        
        # Xác định thời tiết và icon
        if weather.lower() in ['rain', 'drizzle', 'thunderstorm']:
            icon = "☔"
            advice = "📌 **Nhớ mang ô (dù) khi ra ngoài nhé!**"
        elif weather.lower() in ['clear']:
            icon = "☀️"
            advice = "📌 **Nhớ mặc áo chống nắng và bôi kem chống nắng nhé!**"
        elif weather.lower() in ['clouds']:
            icon = "☁️"
            advice = "📌 **Trời nhiều mây, mang áo khoác nhẹ phòng khi se lạnh.**"
        elif weather.lower() in ['snow']:
            icon = "❄️"
            advice = "📌 **Trời lạnh, nhớ mặc ấm và mang khăn choàng nhé!**"
        else:
            icon = "🌤️"
            advice = "📌 **Thời tiết khá ổn, vẫn nên chuẩn bị nhẹ nhàng nhé!**"
        
        # Tạo kết quả
        result = f"🌡️ *Dự báo thời tiết ngày mai tại {city_name}:*\n\n"
        result += f"{icon} Nhiệt độ: {temp}°C (cảm giác như {feels_like}°C)\n"
        result += f"📝 Mô tả: {weather_desc.capitalize()}\n"
        result += f"💧 Độ ẩm: {humidity}%\n"
        result += f"💨 Gió: {wind_speed} km/h\n"
        if rain_prob > 0:
            result += f"🌧️ Khả năng mưa: {rain_prob:.0f}%\n"
        result += f"\n{advice}"
        
        return result
        
    except requests.exceptions.Timeout:
        return "❌ Kết nối API quá chậm. Vui lòng thử lại sau."
    except requests.exceptions.ConnectionError:
        return "❌ Không thể kết nối đến API. Vui lòng kiểm tra kết nối mạng."
    except Exception as e:
        return f"❌ Đã xảy ra lỗi: {str(e)}"

# ─── Hàm login moneytask.top ────────────────────────────────
_DIRECT_HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/plain, */*",
    "Origin": "https://moneytask.top",
    "Referer": "https://moneytask.top/",
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0.0.0 Safari/537.36"
    ),
}

def _direct_post(url: str, json_body: dict) -> requests.Response:
    """POST trực tiếp không qua ZenRows."""
    return requests.post(url, json=json_body, headers=_DIRECT_HEADERS, timeout=30)

def _extract_token(data: dict):
    return (
        data.get("token")
        or data.get("access_token")
        or (data.get("data") or {}).get("token")
        or (data.get("data") or {}).get("access_token")
    )

def mt_login_sync() -> bool:
    """Login moneytask.top — thử ZenRows trước, fallback direct nếu RESP001."""
    global JWT_TOKEN

    payloads = [
        {"phone": MT_USERNAME, "password": MT_PASSWORD},
        {"username": MT_USERNAME, "password": MT_PASSWORD},
    ]

    for pl in payloads:
        key = list(pl.keys())[0]

        # -- Thử ZenRows
        try:
            resp = _zenrows_post(MT_LOGIN_URL, pl)
            print(f"📡 [zenrows/{key}] status={resp.status_code} body={resp.text[:300]}")
            if resp.status_code not in (422, 503):
                try:
                    data = resp.json()
                    token = _extract_token(data)
                    if token:
                        JWT_TOKEN = token
                        print("✅ [zenrows] đăng nhập thành công")
                        return True
                except Exception:
                    pass
        except Exception as e:
            print(f"⚠️ [zenrows/{key}] lỗi: {e}")

        # -- Fallback: direct request
        try:
            resp2 = _direct_post(MT_LOGIN_URL, pl)
            print(f"📡 [direct/{key}] status={resp2.status_code} body={resp2.text[:300]}")
            try:
                data2 = resp2.json()
                token2 = _extract_token(data2)
                if token2:
                    JWT_TOKEN = token2
                    print("✅ [direct] đăng nhập thành công")
                    return True
            except Exception:
                pass
        except Exception as e2:
            print(f"❌ [direct/{key}] lỗi: {e2}")

    print("❌ Login thất bại tất cả payload (zenrows + direct)")
    return False

async def debug_login():
    """Gọi từ /debuglogin để xem raw response login."""
    import urllib.parse
    loop = asyncio.get_running_loop()
    results = []
    payloads = [
        {"phone": MT_USERNAME, "password": MT_PASSWORD},
        {"username": MT_USERNAME, "password": MT_PASSWORD},
    ]
    results.append(f"ZENROWS_API_KEY set: {bool(ZENROWS_API_KEY)}")
    for pl in payloads:
        try:
            def _do(p=pl):
                return _zenrows_post(MT_LOGIN_URL, p)
            resp = await loop.run_in_executor(None, _do)
            results.append(f"payload={list(pl.keys())[0]} status={resp.status_code}")
            results.append(f"body={resp.text[:500]}")
        except Exception as e:
            results.append(f"payload={list(pl.keys())[0]} ERROR={e}")
    return "\n".join(results)

async def mt_login() -> bool:
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, mt_login_sync)

# ─── Hàm lấy dữ liệu task ───────────────────────────────────
def _ensure_chromium():
    """Đảm bảo Playwright có Chromium — tự install nếu thiếu."""
    from playwright.sync_api import sync_playwright
    try:
        with sync_playwright() as p:
            exe = p.chromium.executable_path
            if exe and os.path.exists(exe):
                print(f"✅ [playwright] chromium OK: {exe}")
                return exe
    except Exception:
        pass
    print("⚠️ [playwright] Chromium chưa có — đang cài...")
    subprocess.run([sys.executable, "-m", "playwright", "install", "chromium"])
    try:
        with sync_playwright() as p:
            exe = p.chromium.executable_path
            print(f"✅ [playwright] cài xong: {exe}")
            return exe
    except Exception as e:
        print(f"❌ [playwright] thất bại: {e}")
        return None

def fetch_task_sync(token: str):
    """Fetch task — thử 3 cách: CF Worker proxy → direct → ZenRows."""
    TASK_URL = os.environ.get("MT_TASK_URL", MT_TASK_URL)
    auth = token if token.startswith("Bearer") else f"Bearer {token}"

    headers = {
        "Authorization": auth,
        "Accept": "application/json, text/plain, */*",
        "Accept-Language": "vi-VN,vi;q=0.9,en-US;q=0.8,en;q=0.7",
        "Origin": "https://moneytask.top",
        "Referer": "https://moneytask.top/",
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/124.0.0.0 Safari/537.36"
        ),
    }

    # MT_TASK_URL đã là CF Worker — gọi thẳng
    try:
        r = requests.get(TASK_URL, headers=headers, timeout=30)
        print(f"📡 [fetch] status={r.status_code} body={r.text[:200]}")
        return r.status_code, r.text
    except Exception as e:
        print(f"❌ [fetch] lỗi: {e}")
        return 500, str(e)



async def fetch_task_data():
    global JWT_TOKEN

    # Nếu có static token → dùng luôn, không login
    if _STATIC_TOKEN:
        JWT_TOKEN = _STATIC_TOKEN
        print("🔑 Dùng JWT_TOKEN_STATIC, bỏ qua login")
    elif not JWT_TOKEN:
        print("🔑 Chưa có token, đang login...")
        ok = await mt_login()
        if not ok:
            return {"success": False, "error": "Đăng nhập thất bại", "detail": "Login trả về false"}

    loop = asyncio.get_running_loop()
    status, raw = await loop.run_in_executor(None, fetch_task_sync, JWT_TOKEN)

    # 401 = token hết hạn
    if status == 401:
        if _STATIC_TOKEN:
            return {"success": False, "error": "Token hết hạn", "detail": "Cập nhật JWT_TOKEN_STATIC mới trong env nhé!"}
        print("🔄 Token hết hạn, đăng nhập lại...")
        JWT_TOKEN = ""
        ok = await mt_login()
        if not ok:
            return {"success": False, "error": "Đăng nhập thất bại"}
        status, raw = await loop.run_in_executor(None, fetch_task_sync, JWT_TOKEN)

    try:
        data = json.loads(raw)
    except Exception:
        return {"success": False, "error": f"HTTP {status}", "detail": raw[:400]}

    if status == 200:
        campaigns = data.get("data") if isinstance(data, dict) else data
        return {"success": True, "data": campaigns}

    return {"success": False, "error": f"HTTP {status}", "detail": raw[:400]}

# ─── Format dữ liệu task ────────────────────────────────────
def format_task_data(data):
    if not data or not isinstance(data, list):
        return "❌ Không có dữ liệu"

    lines = []
    total_remaining = 0

    for campaign in data:
        remaining = campaign.get('remaining_views', campaign.get('remaining', 0))
        if remaining <= 0:
            continue

        total_remaining += remaining
        guild_link = campaign.get('guild_link', '')
        ma_so = ''
        if guild_link:
            parts = guild_link.rstrip('/').split('/')
            slug = parts[-1] if parts else ''
            ma_so = slug.split('-')[0] if '-' in slug else slug

        # Chỉ hiển thị: mã số + số lượt còn lại
        lines.append(f"`{ma_so}` — còn {remaining} lượt")

    if not lines:
        return "⚠️ Tất cả mã đã hết lượt hôm nay."

    summary = f"\n📊 *Tổng còn lại: {total_remaining} lượt*"
    return "\n".join(lines) + summary
# ─── /check — thu thập mã từ octolink.vip/5tXx ──────────────
import re as _re
import urllib.parse as _urlparse

OCTOLINK_URL   = "https://octolink.vip/5tXx"
# Pattern: linkhuongdan.online/103-2/?qq=complete  →  mã = "103"
# hoặc linkhuongdan.online/103/?qq=complete        →  mã = "103"
_MA_PATTERN = _re.compile(r"/(\d+)(?:-\d+)?/?\?qq=complete", _re.IGNORECASE)

_FETCH_HEADERS = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0.0.0 Safari/537.36"
    ),
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "vi-VN,vi;q=0.9,en-US;q=0.8,en;q=0.7",
    "Accept-Encoding": "gzip, deflate, br",
    "Cache-Control": "no-cache",
    "Pragma": "no-cache",
    "Referer": "https://google.com/",
}

def _extract_redirect_from_html(html: str, base_url: str = "") -> str | None:
    """
    Tìm URL đích trong HTML — handle:
    1. meta refresh
    2. window.location = / window.location.href =
    3. location.replace( / location.assign(
    4. href trực tiếp chứa 'linkhuongdan'
    """
    # 1. Meta refresh: <meta http-equiv="refresh" content="0;url=...">
    m = _re.search(
        r'<meta[^>]+http-equiv=["\']?refresh["\']?[^>]+content=["\']?\d*\s*;?\s*url=([^\s"\'>\]]+)',
        html, _re.IGNORECASE
    )
    if m:
        return m.group(1).strip().strip('"\'')

    # 2. window.location(.href) = "..."
    m = _re.search(
        r'window\.location(?:\.href)?\s*=\s*["\']([^"\']+)["\']',
        html, _re.IGNORECASE
    )
    if m:
        return m.group(1).strip()

    # 3. location.replace(...) / location.assign(...)
    m = _re.search(
        r'location\.(?:replace|assign)\s*\(\s*["\']([^"\']+)["\']',
        html, _re.IGNORECASE
    )
    if m:
        return m.group(1).strip()

    # 4. Bất kỳ URL nào chứa 'linkhuongdan' trong HTML
    m = _re.search(
        r'(https?://[^\s"\'<>]+linkhuongdan[^\s"\'<>]*)',
        html, _re.IGNORECASE
    )
    if m:
        return m.group(1).strip()

    # 5. href hoặc src chứa qq=complete
    m = _re.search(
        r'(?:href|src|url)\s*=\s*["\']([^"\']*\?qq=complete[^"\']*)["\']',
        html, _re.IGNORECASE
    )
    if m:
        url = m.group(1).strip()
        if url.startswith("http"):
            return url
        if base_url and url.startswith("/"):
            from urllib.parse import urljoin
            return urljoin(base_url, url)

    return None


def _resolve_octolink_sync() -> str | None:
    """
    Theo redirect của octolink tới URL đích cuối cùng.
    Xử lý: HTTP redirect, meta refresh, JS window.location.
    Tối đa 5 bước redirect để không loop mãi.
    """
    session = requests.Session()
    session.headers.update(_FETCH_HEADERS)

    current_url = OCTOLINK_URL
    visited: set[str] = set()

    for step in range(6):
        if current_url in visited:
            break
        visited.add(current_url)

        try:
            r = session.get(
                current_url,
                allow_redirects=False,   # tự xử lý redirect
                timeout=20,
            )
        except Exception as e:
            print(f"[octolink step {step}] GET error: {e}")
            return None

        print(f"[octolink step {step}] {current_url} → status={r.status_code}")

        # HTTP redirect (301/302/303/307/308)
        if r.status_code in (301, 302, 303, 307, 308):
            loc = r.headers.get("Location", "")
            if loc:
                if not loc.startswith("http"):
                    from urllib.parse import urljoin
                    loc = urljoin(current_url, loc)
                current_url = loc
                continue

        # 200 — parse body
        if r.status_code == 200:
            body = r.text
            # Nếu URL sudah mengarah ke linkhuongdan
            if "linkhuongdan" in current_url:
                return current_url
            # Cari redirect di dalam HTML
            found = _extract_redirect_from_html(body, current_url)
            if found:
                if not found.startswith("http"):
                    from urllib.parse import urljoin
                    found = urljoin(current_url, found)
                # Cek langsung apakah sudah ada mã
                if _extract_ma(found):
                    return found
                current_url = found
                continue
            # Tidak ada redirect — kembalikan URL saat ini kalau ada mã
            if _extract_ma(current_url):
                return current_url
            print(f"[octolink step {step}] body snippet: {body[:500]}")
            return None

        print(f"[octolink step {step}] status tidak tertangani: {r.status_code}")
        return None

    # Kalau keluar loop — kembalikan URL terakhir jika ada mã
    return current_url if _extract_ma(current_url) else None

def _extract_ma(url: str) -> str | None:
    """Trích mã số từ URL đích."""
    if not url:
        return None
    m = _MA_PATTERN.search(url)
    if m:
        return m.group(1)
    # fallback: lấy path segment đầu tiên là số
    path = _urlparse.urlparse(url).path
    for seg in path.split("/"):
        seg = seg.split("-")[0]
        if seg.isdigit():
            return seg
    return None

async def octolink_check_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/check — vào octolink.vip/5tXx nhiều lần, thu thập mã không trùng."""
    if not update.message:
        return

    # Số lần thử mặc định = 10, có thể truyền: /check 20
    args = context.args or []
    try:
        tries = max(1, min(50, int(args[0])))
    except (IndexError, ValueError):
        tries = 10

    msg = await update.message.reply_text(
        f"🔍 Đang check {tries} lần từ octolink.vip/5tXx ..."
    )

    loop = asyncio.get_running_loop()
    collected: list[str] = []
    seen: set[str] = set()
    errors = 0

    for i in range(tries):
        try:
            final_url = await loop.run_in_executor(None, _resolve_octolink_sync)
            ma = _extract_ma(final_url) if final_url else None
            if ma and ma not in seen:
                seen.add(ma)
                collected.append(ma)
            elif not ma:
                errors += 1
        except Exception as e:
            errors += 1
            print(f"[check #{i+1}] lỗi: {e}")
        # Nghỉ ngắn tránh rate-limit
        await asyncio.sleep(0.8)

    # ── Gửi kết quả ──
    # Thử 1 lần debug để lấy body snippet nếu hoàn toàn trắng
    debug_snippet = ""
    if not collected:
        try:
            import requests as _req
            _rs = _req.Session()
            _rs.headers.update(_FETCH_HEADERS)
            _rd = _rs.get(OCTOLINK_URL, allow_redirects=False, timeout=15)
            loc = _rd.headers.get("Location", "")
            debug_snippet = (
                f"\n\n🔎 Debug:\nStatus: {_rd.status_code}\n"
                f"Location header: `{loc or '(kosong)'}`\n"
                f"Body:\n`{_rd.text[:300]}`"
            )
        except Exception as _de:
            debug_snippet = f"\n\n🔎 Debug error: {_de}"

    if collected:
        ma_list = "\n".join(f"  `{m}`" for m in collected)
        out = (
            f"✅ *Check hoàn tất* ({tries} lần)\n\n"
            f"📦 *Số mã thu được: {len(collected)}*\n\n"
            f"{ma_list}\n\n"
            f"❌ Lỗi/trống: {errors} lần\n"
            f"⏰ {datetime.now().strftime('%H:%M:%S %d/%m/%Y')}"
        )
    else:
        out = (
            f"⚠️ Không lấy được mã nào sau {tries} lần.\n"
            f"Lỗi: {errors}"
            f"{debug_snippet}\n"
            f"⏰ {datetime.now().strftime('%H:%M:%S %d/%m/%Y')}"
        )

    try:
        await msg.edit_text(out, parse_mode="Markdown")
    except Exception:
        await update.message.reply_text(out, parse_mode="Markdown")

# ─── Handler check task ──────────────────────────────────────
async def check_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    msg = await update.message.reply_text("🔍 Đang lấy dữ liệu task...")
    try:
        result = await asyncio.wait_for(fetch_task_data(), timeout=120)
    except asyncio.TimeoutError:
        await msg.edit_text("⏱ *Timeout:* Không lấy được dữ liệu sau 120s.\nThử lại sau.", parse_mode="Markdown")
        return
    except Exception as e:
        await msg.edit_text(f"❌ *Exception:*\n`{e}`", parse_mode="Markdown")
        return

    if not result["success"]:
        detail = result.get("detail", "")
        err_text = f"❌ *Lỗi lấy task:*\n`{result['error']}`"
        if detail:
            err_text += f"\n\nDetail:\n`{detail[:400]}`"
        try:
            await msg.edit_text(err_text, parse_mode="Markdown")
        except Exception:
            await update.message.reply_text(err_text, parse_mode="Markdown")
        return

    formatted = format_task_data(result["data"])
    out = (
        f"📊 *Làm việc đi mấy thằng gay*\n\n{formatted}\n\n"
        f"⏰ {datetime.now().strftime('%H:%M:%S %d/%m/%Y')}"
    )
    try:
        await msg.edit_text(out, parse_mode="Markdown")
    except Exception:
        await update.message.reply_text(out, parse_mode="Markdown")

# Set lưu mã số từ lần check trước (chỉ cho auto)
_prev_ma_set: set = set()

def extract_ma_set(data) -> set:
    """Trích tập hợp mã số còn lượt từ data"""
    result = set()
    if not data or not isinstance(data, list):
        return result
    for campaign in data:
        remaining = campaign.get('remaining_views', campaign.get('remaining', 0))
        if remaining <= 0:
            continue
        guild_link = campaign.get('guild_link', '')
        if guild_link:
            parts = guild_link.rstrip('/').split('/')
            slug = parts[-1] if parts else ''
            ma_so = slug.split('-')[0] if '-' in slug else slug
            if ma_so:
                result.add(ma_so)
    return result

# ─── Tự động gửi task ──────────────────────────────────────
async def auto_task_callback(context: ContextTypes.DEFAULT_TYPE):
    global last_task_message_id, last_task_chat_id, _prev_ma_set
    if not auto_task_enabled:
        return
    result = await fetch_task_data()
    if not result["success"]:
        return

    data = result["data"]
    formatted = format_task_data(data)

    # So sánh mã mới / mất so với lần trước
    curr_ma_set = extract_ma_set(data)
    new_codes  = curr_ma_set - _prev_ma_set
    lost_codes = _prev_ma_set - curr_ma_set
    change_lines = []
    if new_codes:
        change_lines.append(f"🆕 *Mã mới nè các con vợ:* {','.join(sorted(new_codes))}")
    if lost_codes:
        change_lines.append(f"💀 *Mất mẹ mã này rồi:* {','.join(sorted(lost_codes))}")
    _prev_ma_set = curr_ma_set

    now_vn = (datetime.utcnow() + timedelta(hours=7)).strftime('%H:%M:%S %d/%m/%Y')
    text = (
        f"🤖 *Làm việc đi mấy thằng gay -auto:*\n\n"
        f"{formatted}\n"
    )
    if change_lines:
        text += "\n" + "\n".join(change_lines) + "\n"
    text += f"\n⏰ {now_vn}"
    if last_task_chat_id:
        try:
            if last_task_message_id:
                await context.bot.delete_message(chat_id=last_task_chat_id, message_id=last_task_message_id)
        except Exception as e:
            print(f"⚠️ Không xóa được tin cũ: {e}")
        try:
            sent = await context.bot.send_message(chat_id=last_task_chat_id, text=text, parse_mode="Markdown")
            last_task_message_id = sent.message_id
        except Exception as e:
            print(f"⚠️ Không gửi được tin mới: {e}")

# ─── Handler /tudong ──────────────────────────────────────────
async def tudong_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global auto_task_enabled, auto_task_job, last_task_chat_id, last_task_message_id
    if not update.message:
        return
    user_id = update.effective_user.id
    if user_id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền!")
        return

    args = context.args
    if not args:
        # Toggle cũ nếu không có tham số
        auto_task_enabled = not auto_task_enabled
    else:
        cmd = args[0].lower()
        if cmd == "on":
            auto_task_enabled = True
        elif cmd == "off":
            auto_task_enabled = False
        else:
            await update.message.reply_text("❌ Sai cú pháp. Dùng: /tudong [on|off] (hoặc /tudong để toggle)")
            return

    # LUÔN hủy job cũ trước khi set trạng thái mới
    if auto_task_job:
        try:
            auto_task_job.schedule_removal()
        except:
            pass
        auto_task_job = None

    if auto_task_enabled:
        job_queue = context.job_queue
        if job_queue:
            # Tạo job mới, first=0 để chạy ngay
            auto_task_job = job_queue.run_repeating(auto_task_callback, interval=300, first=0)
            last_task_chat_id = update.effective_chat.id
            last_task_message_id = None
            await update.message.reply_text("✅ Đã bật tự động cập nhật task mỗi 5 phút.")
        else:
            auto_task_enabled = False
            await update.message.reply_text("❌ Không có job queue!")
    else:
        # Tắt: xóa tin nhắn cũ
        try:
            if last_task_message_id and last_task_chat_id:
                await context.bot.delete_message(chat_id=last_task_chat_id, message_id=last_task_message_id)
        except:
            pass
        last_task_message_id = None
        last_task_chat_id = None
        await update.message.reply_text("🔇 Đã tắt tự động cập nhật.")
# ─── Handlers ────────────────────────────────────────────────
def _search_top10(query: str) -> list[dict]:
    """Tìm top 10 bài hát từ YouTube, trả về list dict {id, title, url}."""
    ydl_opts = {
        "quiet": True,
        "no_warnings": True,
        "noplaylist": True,
        "skip_download": True,
        "extract_flat": "in_playlist",
        "http_headers": {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Accept-Language": "en-US,en;q=0.9",
        },
    }
    with yt_dlp.YoutubeDL(ydl_opts) as ydl:
        results = ydl.extract_info(f"ytsearch10:{query}", download=False)
        if results and "entries" in results:
            entries = [e for e in results["entries"] if e and e.get("id")]
            out = []
            for e in entries[:10]:
                out.append({
                    "id": e["id"],
                    "title": e.get("title", "Unknown"),
                    "url": f"https://www.youtube.com/watch?v={e['id']}",
                })
            return out
    return []


# ─── Cache bài tìm kiếm (chat_id → list bài) ─────────────────
_music_search_cache: dict = {}


async def music_pick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Xử lý khi user bấm nút chọn bài → tải và gửi MP3."""
    cbq = update.callback_query
    await cbq.answer()

    # data format: muspick_{chat_id}_{index}
    parts = cbq.data.split("_")
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
        idx = int(parts[2])
    except ValueError:
        return

    entries = _music_search_cache.get(chat_id)
    if not entries or idx >= len(entries):
        await cbq.edit_message_text("❌ Phiên tìm kiếm đã hết hạn. Dùng /music lại nhé!")
        return

    chosen = entries[idx]
    title = chosen["title"]
    video_id = chosen["id"]

    msg = await cbq.edit_message_text(
        f"⏳ Đang tải: *{title}*...", parse_mode="Markdown"
    )

    try:
        loop = asyncio.get_running_loop()

        def _dl():
            import glob as _glob
            os.makedirs("/tmp", exist_ok=True)
            MAX_FILE_MB = 44
            real_title = title

            # ── Thử YouTube trước ────────────────────────────
            try:
                out_tmpl = f"/tmp/muspick_{video_id}.%(ext)s"
                ydl_opts = {
                    "format": "bestaudio[abr<=128]/bestaudio/best",
                    "max_filesize": MAX_FILE_MB * 1024 * 1024,
                    "outtmpl": out_tmpl,
                    "postprocessors": [{
                        "key": "FFmpegExtractAudio",
                        "preferredcodec": "mp3",
                        "preferredquality": "96",
                    }],
                    "quiet": False,
                    "no_warnings": False,
                    "noplaylist": True,
                    "ignoreerrors": False,
                    "no_check_certificate": True,
                    "socket_timeout": 45,
                    "extractor_args": {
                        "youtube": {
                            "player_client": ["android", "web"],
                        }
                    },
                }
                url = f"https://www.youtube.com/watch?v={video_id}"
                with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                    info = ydl.extract_info(url, download=True)
                    if info:
                        real_title = info.get("title", title)

                matches = _glob.glob(f"/tmp/muspick_{video_id}*.mp3")
                if matches:
                    fp = matches[0]
                    size_mb = os.path.getsize(fp) / (1024 * 1024)
                    if size_mb > MAX_FILE_MB:
                        os.remove(fp)
                        raise Exception(f"File quá lớn ({size_mb:.1f} MB)")
                    return fp, real_title
                raise Exception("Không tìm thấy file MP3")

            except Exception as yt_err:
                print(f"[YT] thất bại: {yt_err} — thử SoundCloud...")

            # ── Fallback SoundCloud ──────────────────────────
            sc_query = real_title or title
            sc_out = f"/tmp/muspick_sc_{video_id}.%(ext)s"
            sc_opts = {
                "format": "bestaudio[abr<=128]/bestaudio/best",
                "max_filesize": MAX_FILE_MB * 1024 * 1024,
                "outtmpl": sc_out,
                "postprocessors": [{
                    "key": "FFmpegExtractAudio",
                    "preferredcodec": "mp3",
                    "preferredquality": "96",
                }],
                "quiet": False,
                "no_warnings": False,
                "noplaylist": True,
                "ignoreerrors": False,
                "no_check_certificate": True,
                "socket_timeout": 45,
                "default_search": "scsearch1",
            }
            with yt_dlp.YoutubeDL(sc_opts) as ydl:
                info = ydl.extract_info(sc_query, download=True)
                if info and "entries" in info:
                    info = info["entries"][0]
                if info:
                    real_title = info.get("title", sc_query)

            matches = _glob.glob(f"/tmp/muspick_sc_{video_id}*.mp3")
            if not matches:
                all_mp3 = sorted(_glob.glob("/tmp/*.mp3"), key=os.path.getmtime, reverse=True)
                matches = all_mp3[:1]
            if not matches:
                raise Exception("Không tải được bài hát từ cả YouTube lẫn SoundCloud. Thử bài khác!")
            fp = matches[0]
            size_mb = os.path.getsize(fp) / (1024 * 1024)
            if size_mb > MAX_FILE_MB:
                os.remove(fp)
                raise Exception(f"File quá lớn ({size_mb:.1f} MB). Thử bài khác nhé!")
            return fp, real_title

        filepath, real_title = await loop.run_in_executor(None, _dl)

        await msg.edit_text(f"📤 Đang gửi: *{real_title}*", parse_mode="Markdown")
        with open(filepath, "rb") as f:
            await cbq.message.reply_audio(audio=f, title=real_title, caption=f"🎵 {real_title}")
        try:
            os.remove(filepath)
        except:
            pass
        await msg.delete()

    except Exception as e:
        await msg.edit_text(f"❌ Lỗi: {str(e)}\n\nThử bài khác hoặc dùng /music lại!")


async def music(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    chat_id = update.effective_chat.id
    args = context.args
    if args:
        query = " ".join(args)
        msg = await update.message.reply_text(
            f"🔍 Đang tìm: *{query}*...", parse_mode="Markdown"
        )
        try:
            loop = asyncio.get_running_loop()
            entries = await loop.run_in_executor(None, lambda: _search_top10(query))

            if not entries:
                await msg.edit_text("❌ Không tìm được kết quả. Thử tên khác nhé!")
                return

            _music_search_cache[chat_id] = entries

            lines = [f"🔎 *Kết quả tìm kiếm: {query}*\n"]
            for i, e in enumerate(entries):
                lines.append(f"`{i+1}.` {e['title']}")
            text = "\n".join(lines)

            keyboard = []
            row = []
            for i, e in enumerate(entries):
                btn = InlineKeyboardButton(
                    f"{'🎵' if i % 2 == 0 else '🎶'} {i+1}. {e['title'][:28]}",
                    callback_data=f"muspick_{chat_id}_{i}"
                )
                row.append(btn)
                if len(row) == 2:
                    keyboard.append(row)
                    row = []
            if row:
                keyboard.append(row)

            await msg.edit_text(
                text,
                reply_markup=InlineKeyboardMarkup(keyboard),
                parse_mode="Markdown",
            )
        except Exception as e:
            await msg.edit_text(f"❌ Lỗi: {str(e)}\n\nThử lại với tên khác nhé!")
        return

    # ── Không có args → tìm 10 bài trending + hiện nút chọn ──
    _set_music_active(chat_id, True)
    msg = await update.message.reply_text("🔍 Đang tải danh sách nhạc hot...", parse_mode="Markdown")

    try:
        loop = asyncio.get_running_loop()
        # Chọn ngẫu nhiên 1 trong 5 query trending để đa dạng
        trending_queries = [
            "vpop nhạc việt hot 2025",
            "nhạc trẻ việt nam trending 2025",
            "nhạc việt hay nhất tháng này",
            "bài hát việt nam mới nhất hot",
            "top vpop bxh âm nhạc 2025",
        ]
        q = random.choice(trending_queries)
        entries = await loop.run_in_executor(None, lambda: _search_top10(q))

        if not entries:
            await msg.edit_text("❌ Không tìm được danh sách. Thử lại nhé!\n\nHoặc dùng: `/music tên bài`", parse_mode="Markdown")
            return

        # Lưu cache
        _music_search_cache[chat_id] = entries

        # Build text list
        lines = ["🎵 *10 bài nhạc hot — chọn bài muốn nghe:*\n"]
        for i, e in enumerate(entries):
            lines.append(f"`{i+1}.` {e['title']}")
        text = "\n".join(lines)

        # Build keyboard: mỗi hàng 2 nút
        keyboard = []
        row = []
        for i, e in enumerate(entries):
            btn = InlineKeyboardButton(
                f"{'🎵' if i % 2 == 0 else '🎶'} {i+1}. {e['title'][:28]}",
                callback_data=f"muspick_{chat_id}_{i}"
            )
            row.append(btn)
            if len(row) == 2:
                keyboard.append(row)
                row = []
        if row:
            keyboard.append(row)

        await msg.edit_text(
            text,
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="Markdown",
        )

    except Exception as e:
        await msg.edit_text(
            f"❌ Lỗi: {str(e)}\n\nThử dùng: `/music tên bài hát`",
            parse_mode="Markdown",
        )

