async def handle_weather_reply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global weather_context, weather_active
    
    if not update.message:
        return
    
    if not weather_active:
        return
    
    user_id = update.effective_user.id
    
    if user_id not in weather_context or weather_context[user_id].get("step") != "ask_location":
        return
    
    reply = update.message.reply_to_message
    if not reply or reply.from_user.id != context.bot.id:
        return
    
    city = update.message.text.strip()
    if not city:
        await update.message.reply_text("❌ Vui lòng nhập tên thành phố hợp lệ.")
        return
    
    weather_type = weather_context[user_id].get("type", "forecast")
    
    msg = await update.message.reply_text(f"🔍 Đang tra cứu thời tiết cho *{city}*...", parse_mode="Markdown")
    
    if weather_type == "current":
        weather_info = get_current_weather(city)
    else:
        weather_info = get_weather_forecast(city)
    
    await msg.edit_text(weather_info, parse_mode="Markdown")
    asyncio.create_task(_auto_delete(context.bot, msg.chat_id, msg.message_id, 300))
    
    if user_id in weather_context:
        del weather_context[user_id]
    
    weather_active = False

