async def checkgay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    reply = update.message.reply_to_message
    if reply:
        target_id = reply.from_user.id
        target_name = reply.from_user.full_name or reply.from_user.username or str(target_id)
    else:
        target_id = update.effective_user.id
        target_name = update.effective_user.full_name or update.effective_user.username or str(target_id)

    if target_id in GAY_DICT:
        name = GAY_DICT[target_id]["name"]
        dogay = GAY_DICT[target_id]["dogay"]
        await update.message.reply_text(
            f"🏳️‍🌈 *{name} là gay!*\n🌈 Độ gay: *{dogay}*\n\nChào mừng bạn đến với cộng đồng! 🥳",
            parse_mode="Markdown"
        )
    else:
        await update.message.reply_text(
            f"❌ *{target_name} không phải là gay!*\n\nRất tiếc, không nằm trong danh sách đặc biệt này. 😄",
            parse_mode="Markdown"
        )

# ─── Handler addgay ──────────────────────────────────────────
async def addgay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    user_id = update.effective_user.id
    if user_id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    reply = update.message.reply_to_message
    if reply:
        target = reply.from_user
        target_id = target.id
        name = target.full_name or target.username or str(target_id)
        GAY_DICT[target_id] = {"name": name, "dogay": 50}
        await update.message.reply_text(
            f"✅ Đã thêm `{name}` (ID: `{target_id}`) vào danh sách gay!\n"
            f"📊 Hiện có {len(GAY_DICT)} người trong danh sách.",
            parse_mode="Markdown"
        )
        return

    args = context.args
    if not args:
        await update.message.reply_text(
            "📝 *Cách dùng:* `/addgay` (reply tin nhắn của người đó) hoặc `/addgay ID`\n"
            "Ví dụ: `/addgay 123456789`",
            parse_mode="Markdown"
        )
        return

    try:
        new_id = int(args[0])
        try:
            chat = await context.bot.get_chat(new_id)
            name = chat.full_name or chat.username or str(new_id)
        except Exception:
            name = str(new_id)
        GAY_DICT[new_id] = {"name": name, "dogay": 50}
        await update.message.reply_text(
            f"✅ Đã thêm `{name}` (ID: `{new_id}`) vào danh sách gay!\n"
            f"📊 Hiện có {len(GAY_DICT)} người trong danh sách.",
            parse_mode="Markdown"
        )
    except ValueError:
        await update.message.reply_text("❌ Vui lòng nhập ID hợp lệ (chỉ số)!")

# ─── Handler xoagay ──────────────────────────────────────────
async def xoagay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    user_id = update.effective_user.id
    if user_id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    args = context.args
    if not args:
        await update.message.reply_text(
            "📝 *Cách dùng:* `/xoagay ID`\n"
            "Ví dụ: `/xoagay 123456789`\n"
            "Hoặc: `/xoagay all` để xóa toàn bộ",
            parse_mode="Markdown"
        )
        return

    if args[0].lower() == "all":
        GAY_DICT.clear()
        await update.message.reply_text("🗑️ Đã xóa toàn bộ danh sách gay!")
        return

    try:
        remove_id = int(args[0])
        if remove_id in GAY_DICT:
            name = GAY_DICT.pop(remove_id)["name"]
            await update.message.reply_text(
                f"✅ Đã xóa `{name}` (ID: `{remove_id}`) khỏi danh sách gay!\n"
                f"📊 Hiện còn {len(GAY_DICT)} người trong danh sách.",
                parse_mode="Markdown"
            )
        else:
            await update.message.reply_text(f"❌ Không tìm thấy ID `{remove_id}` trong danh sách!", parse_mode="Markdown")
    except ValueError:
        await update.message.reply_text("❌ Vui lòng nhập ID hợp lệ (chỉ số)!")
# ─── Handler randomgay ───────────────────────────────────────
async def randomgay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    user_id = update.effective_user.id
    if user_id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    if not GAY_DICT:
        await update.message.reply_text("📭 Danh sách gay hiện đang trống! Hãy thêm ID bằng `/addgay`.")
        return

    import random
    uid, info = random.choice(list(GAY_DICT.items()))
    await update.message.reply_text(
        f"🎲 *Random gay:*\n\n"
        f"🏳️‍🌈 `{info['name']}` (ID: `{uid}`) - Độ gay: *{info['dogay']}*\n"
        f"📊 Hiện có {len(GAY_DICT)} người trong danh sách.",
        parse_mode="Markdown"
    )
# ─── Handler gaylist ─────────────────────────────────────────
async def gaylist(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    user_id = update.effective_user.id
    if user_id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    if not GAY_DICT:
        await update.message.reply_text("📭 Danh sách gay hiện đang trống!")
        return

    items = list(GAY_DICT.items())
    lines = [f"• {info['name']} (ID: `{uid}`) - Độ gay: *{info['dogay']}*" for uid, info in items[:20]]
    suffix = f"\n⚠️ Hiển thị 20/{len(items)} người." if len(items) > 20 else ""
    await update.message.reply_text(
        f"📋 *Danh sách gay:*\n\n" + "\n".join(lines) + suffix +
        f"\n\n📊 Tổng: {len(items)} người",
        parse_mode="Markdown"
    )

# ─── Handler /dogay ──────────────────────────────────────────
async def dogay_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    if update.effective_user.id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    args = context.args
    reply = update.message.reply_to_message

    # /dogay [số] khi reply
    if reply and args:
        try:
            val = int(args[0])
            if not (0 <= val <= 100):
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Độ gay phải là số từ 0 đến 100!")
            return
        target_id = reply.from_user.id
        if target_id not in GAY_DICT:
            await update.message.reply_text("❌ Người này không có trong danh sách gay!")
            return
        GAY_DICT[target_id]["dogay"] = val
        await update.message.reply_text(
            f"✅ Đã cập nhật độ gay của `{GAY_DICT[target_id]['name']}` thành *{val}*!",
            parse_mode="Markdown"
        )
        return

    # /dogay ID số
    if args and len(args) >= 2:
        try:
            target_id = int(args[0])
            val = int(args[1])
            if not (0 <= val <= 100):
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Cú pháp: `/dogay ID số` hoặc reply + `/dogay số`\nĐộ gay từ 0-100.", parse_mode="Markdown")
            return
        if target_id not in GAY_DICT:
            await update.message.reply_text("❌ ID này không có trong danh sách gay!")
            return
        GAY_DICT[target_id]["dogay"] = val
        await update.message.reply_text(
            f"✅ Đã cập nhật độ gay của `{GAY_DICT[target_id]['name']}` thành *{val}*!",
            parse_mode="Markdown"
        )
        return

    await update.message.reply_text(
        "📝 *Cách dùng:*\n"
        "• Reply tin nhắn + `/dogay 80`\n"
        "• `/dogay 123456789 80`",
        parse_mode="Markdown"
    )

