# Hàm xử lý lệnh /trogiup (đặt ở vị trí bất kỳ, sau các handler khác)
# ─── Tài Xỉu System ──────────────────────────────────────────
# Lưu số coin của từng user {user_id: coin}
COIN_DB: dict = {}
DEFAULT_COIN = 10

# Redeem codes: {code: {"coin": int, "used_by": set()}}
# used_by = set of user_ids đã dùng (mỗi user chỉ dùng 1 lần)
REDEEM_CODES: dict = {}

# Lưu trạng thái game đang diễn ra {user_id: {...}}
TAIXIU_GAMES: dict = {}

# Bật/tắt tính năng tài xỉu (admin)
TAIXIU_ENABLED: bool = True

# Lịch sử các phiên theo chat {chat_id: [{"name","amount","dice","total","result","choice","win","time"}, ...]}
TAIXIU_HISTORY: dict = {}
MAX_HISTORY = 20   # giữ tối đa 20 phiên gần nhất mỗi nhóm

# ─── Trade System ─────────────────────────────────────────────
# TRADE_PENDING: {target_user_id: {"from_id": int, "from_name": str, "amount": int, "chat_id": int, "msg_id": int, "time": float}}
TRADE_PENDING: dict = {}
TRADE_EXPIRY = 120  # giây — 2 phút để xác nhận

# Thời gian tự xoá phiên (giây)
SESSION_EXPIRY = 300  # 5 phút — đủ thời gian người chơi suy nghĩ

DICE_HIDDEN = "🎲"
DICE_FACES  = ["⚀","⚁","⚂","⚃","⚄","⚅"]   # index = value-1

def get_coin(user_id: int) -> int:
    return COIN_DB.get(user_id, DEFAULT_COIN)

def set_coin(user_id: int, amount: int):
    COIN_DB[user_id] = amount

async def _session_expiry_task(uid: int, bot):
    """Sau SESSION_EXPIRY giây không tương tác thì tự huỷ phiên."""
    await asyncio.sleep(SESSION_EXPIRY)
    game = TAIXIU_GAMES.pop(uid, None)
    if not game:
        return  # đã kết thúc bình thường
    # Xoá tin nhắn bàn cược
    try:
        await bot.delete_message(
            chat_id=game["chat_id"],
            message_id=game["msg_id"],
        )
    except Exception:
        pass
    # Thông báo phiên hết hạn — không hoàn coin
    try:
        expired_time = datetime.now().strftime("%H:%M:%S %d/%m/%Y")
        amount = game.get("amount", 0)
        msg = (
            f"⏰ Phiên tài xỉu đã hết hạn do không tương tác.\n"
            f"💸 Mất *{amount} coin* do bỏ cuộc.\n"
            f"🕐 Hết hạn lúc: *{expired_time}*"
        )
        sent = await bot.send_message(
            chat_id=game["chat_id"],
            text=msg,
            parse_mode="Markdown",
        )
        asyncio.create_task(_auto_delete(bot, game["chat_id"], sent.message_id, 10))
    except Exception:
        pass

async def _auto_delete(bot, chat_id: int, message_id: int, delay: int):
    """Tự xoá tin nhắn sau delay giây."""
    await asyncio.sleep(delay)
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except Exception:
        pass

# ─── /trade ──────────────────────────────────────────────────
async def trade_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/trade <số_coin> — reply vào tin nhắn người muốn trade để gửi đề nghị.
    /trade ok — đồng ý nhận trade.
    /trade deo — từ chối trade.
    """
    if not update.message:
        return

    uid   = update.effective_user.id
    uname = update.effective_user.first_name or update.effective_user.username or str(uid)
    args  = context.args

    # ── /trade ok — xác nhận nhận coin ──────────────────────
    if args and args[0].lower() == "ok":
        pending = TRADE_PENDING.get(uid)
        if not pending:
            s = await update.message.reply_text("❌ Không có ai đang gửi trade cho bạn!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
            return
        # Kiểm tra hết hạn
        if time.time() - pending["time"] > TRADE_EXPIRY:
            TRADE_PENDING.pop(uid, None)
            s = await update.message.reply_text("❌ Đề nghị trade đã hết hạn (2 phút)!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
            return

        from_id   = pending["from_id"]
        from_name = pending["from_name"]
        amount    = pending["amount"]

        # Kiểm tra sender vẫn còn đủ coin
        sender_coin = get_coin(from_id)
        if sender_coin < amount:
            TRADE_PENDING.pop(uid, None)
            s = await update.message.reply_text(
                f"❌ *{from_name}* không còn đủ coin để trade (hiện có *{sender_coin}*).",
                parse_mode="Markdown"
            )
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 10))
            return

        # Chuyển coin
        set_coin(from_id, sender_coin - amount)
        set_coin(uid, get_coin(uid) + amount)
        TRADE_PENDING.pop(uid, None)

        msg = (
            f"✅ *Trade thành công!*\n\n"
            f"💸 *{from_name}* → *{uname}*\n"
            f"💰 Số coin: *{amount}*\n\n"
            f"📊 Số dư sau trade:\n"
            f"• {from_name}: *{get_coin(from_id)} coin*\n"
            f"• {uname}: *{get_coin(uid)} coin*"
        )
        sent = await update.message.reply_text(msg, parse_mode="Markdown")
        asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 60))
        return

    # ── /trade deo — từ chối ─────────────────────────────────
    if args and args[0].lower() == "deo":
        pending = TRADE_PENDING.get(uid)
        if not pending:
            s = await update.message.reply_text("❌ Không có trade nào đang chờ bạn xác nhận!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
            return
        from_name = pending["from_name"]
        amount    = pending["amount"]
        TRADE_PENDING.pop(uid, None)
        msg = (
            f"❌ *{uname}* đã từ chối nhận *{amount} coin* từ *{from_name}*."
        )
        sent = await update.message.reply_text(msg, parse_mode="Markdown")
        asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 20))
        return

    # ── /trade <số_coin> — phải reply vào tin nhắn target ───
    reply = update.message.reply_to_message
    if not reply:
        s = await update.message.reply_text(
            "📝 *Cách dùng:*\n"
            "1️⃣ Reply tin nhắn người muốn trade + `/trade <số_coin>`\n"
            "2️⃣ Người nhận gõ `/trade ok` để đồng ý\n"
            "3️⃣ Hoặc `/trade deo` để từ chối\n\n"
            "⏰ Đề nghị tự huỷ sau *2 phút*.",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 20))
        return

    if not args:
        s = await update.message.reply_text(
            "❌ Bạn chưa nhập số coin!\n📝 Cú pháp: reply + `/trade <số_coin>`",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
        return

    try:
        amount = int(args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        s = await update.message.reply_text("❌ Số coin phải là số nguyên dương!")
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
        return

    target_user = reply.from_user
    if not target_user or target_user.id == uid:
        s = await update.message.reply_text("❌ Không thể trade với chính mình!")
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
        return
    if target_user.is_bot:
        s = await update.message.reply_text("❌ Không thể trade với bot!")
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
        return

    target_id   = target_user.id
    target_name = target_user.first_name or target_user.username or str(target_id)

    # Kiểm tra người gửi có đủ coin
    sender_coin = get_coin(uid)
    if sender_coin < amount:
        s = await update.message.reply_text(
            f"❌ Bạn không đủ coin! Hiện có *{sender_coin} coin*, muốn trade *{amount}*.",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 10))
        return

    # Kiểm tra target đã có pending chưa
    existing = TRADE_PENDING.get(target_id)
    if existing and time.time() - existing["time"] <= TRADE_EXPIRY:
        s = await update.message.reply_text(
            f"❌ *{target_name}* đang có 1 đề nghị trade khác đang chờ xác nhận!",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 10))
        return

    # Lưu pending
    TRADE_PENDING[target_id] = {
        "from_id":   uid,
        "from_name": uname,
        "amount":    amount,
        "chat_id":   update.effective_chat.id,
        "time":      time.time(),
    }

    msg = (
        f"🔄 *{uname}* muốn trade *{amount} coin* cho *{target_name}*!\n\n"
        f"👉 *{target_name}*, reply:\n"
        f"• `/trade ok` — đồng ý nhận\n"
        f"• `/trade deo` — từ chối\n\n"
        f"⏰ Tự huỷ sau *2 phút*."
    )
    sent = await update.message.reply_text(msg, parse_mode="Markdown")
    # Auto huỷ pending sau TRADE_EXPIRY
    asyncio.create_task(_trade_expire(target_id, context.bot, update.effective_chat.id, sent.message_id))


async def _trade_expire(target_id: int, bot, chat_id: int, msg_id: int):
    """Sau TRADE_EXPIRY giây, tự xoá pending trade nếu chưa xử lý."""
    await asyncio.sleep(TRADE_EXPIRY)
    removed = TRADE_PENDING.pop(target_id, None)
    if removed:
        try:
            await bot.delete_message(chat_id=chat_id, message_id=msg_id)
        except Exception:
            pass
        try:
            expired_msg = await bot.send_message(
                chat_id=chat_id,
                text=f"⏰ Đề nghị trade *{removed['amount']} coin* từ *{removed['from_name']}* đã hết hạn.",
                parse_mode="Markdown"
            )
            asyncio.create_task(_auto_delete(bot, chat_id, expired_msg.message_id, 10))
        except Exception:
            pass


