# ─── /addcoin (admin) ────────────────────────────────────────
async def addcoin_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    if update.effective_user.id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return

    reply = update.message.reply_to_message
    args  = context.args

    # ── Trường hợp 1: reply tin nhắn → /addcoin <số>
    if reply:
        if not args:
            await update.message.reply_text(
                "📝 *Cách dùng:* Reply tin nhắn rồi `/addcoin <số>`\n"
                "Ví dụ: `/addcoin 100`",
                parse_mode="Markdown"
            )
            return
        try:
            amount = int(args[0])
        except ValueError:
            await update.message.reply_text("❌ Số coin phải là số nguyên!")
            return
        if amount == 0:
            await update.message.reply_text("❌ Số coin phải khác 0!")
            return
        target_id   = reply.from_user.id
        target_name = reply.from_user.full_name or reply.from_user.username or str(target_id)
        new_total   = get_coin(target_id) + amount
        if new_total < 0:
            new_total = 0
        set_coin(target_id, new_total)
        sign = "+" if amount > 0 else ""
        await update.message.reply_text(
            f"✅ Đã cộng *{sign}{amount} coin* cho *{target_name}*\n"
            f"💰 Tổng coin hiện tại: *{new_total}*",
            parse_mode="Markdown"
        )
        return

    # ── Trường hợp 2: /addcoin <user_id> <số>
    if not args or len(args) < 2:
        await update.message.reply_text(
            "📝 *Cách dùng:*\n"
            "• Reply tin nhắn + `/addcoin <số>`\n"
            "• `/addcoin <user_id> <số>`\n\n"
            "Ví dụ: `/addcoin 123456789 100`\n"
            "Số âm sẽ trừ coin.",
            parse_mode="Markdown"
        )
        return
    try:
        target_id = int(args[0])
        amount    = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ ID và số coin phải là số nguyên!")
        return
    if amount == 0:
        await update.message.reply_text("❌ Số coin phải khác 0!")
        return
    try:
        chat = await context.bot.get_chat(target_id)
        target_name = chat.full_name or chat.username or str(target_id)
    except Exception:
        target_name = str(target_id)
    new_total = get_coin(target_id) + amount
    if new_total < 0:
        new_total = 0
    set_coin(target_id, new_total)
    sign = "+" if amount > 0 else ""
    await update.message.reply_text(
        f"✅ Đã cộng *{sign}{amount} coin* cho *{target_name}* (ID: `{target_id}`)\n"
        f"💰 Tổng coin hiện tại: *{new_total}*",
        parse_mode="Markdown"
    )

# ─── /taixiu <số> & /tx <số|all> ────────────────────────────
async def tx_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/tx là rút gọn của /taixiu. Hỗ trợ /tx <số>, /tx all, /tx history, /tx taocode, /tx redeem"""
    if not update.message:
        return
    uid = update.effective_user.id
    args = context.args

    # ── /tx taocode <code> <số_coin> — chỉ admin ─────────────
    if args and args[0].lower() == "taocode":
        if uid != ADMIN_ID:
            s = await update.message.reply_text("❌ Bạn không có quyền tạo code!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 5))
            return
        if len(args) < 3:
            await update.message.reply_text(
                "📝 *Cách dùng:* `/tx taocode <code> <số_coin>`\n"
                "Ví dụ: `/tx taocode SUMMER2025 500`",
                parse_mode="Markdown"
            )
            return
        code = args[1].upper()
        try:
            coin_val = int(args[2])
            if coin_val <= 0:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Số coin phải là số nguyên dương!")
            return
        REDEEM_CODES[code] = {"coin": coin_val, "used_by": set()}
        await update.message.reply_text(
            f"✅ Đã tạo code *{code}* — trị giá *{coin_val} coin*\n"
            f"Mỗi user chỉ dùng được 1 lần.",
            parse_mode="Markdown"
        )
        return

    # ── /tx redeem <code> — user nhập code để nhận coin ──────
    if args and args[0].lower() == "redeem":
        if len(args) < 2:
            await update.message.reply_text(
                "📝 *Cách dùng:* `/tx redeem <code>`\n"
                "Ví dụ: `/tx redeem SUMMER2025`",
                parse_mode="Markdown"
            )
            return
        code = args[1].upper()
        if code not in REDEEM_CODES:
            s = await update.message.reply_text("❌ Code không tồn tại hoặc đã bị xoá!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
            return
        entry = REDEEM_CODES[code]
        if uid in entry["used_by"]:
            s = await update.message.reply_text("❌ Bạn đã dùng code này rồi!")
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 8))
            return
        # Cộng coin
        entry["used_by"].add(uid)
        new_total = get_coin(uid) + entry["coin"]
        set_coin(uid, new_total)
        name = update.effective_user.first_name or "bạn"
        sent = await update.message.reply_text(
            f"🎉 *{name}* đã nhận thành công code *{code}*!\n"
            f"💰 +{entry['coin']} coin\n"
            f"💼 Tổng coin hiện tại: *{new_total}*",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 30))
        return

    # /tx history → xem cầu nhóm
    if args and args[0].lower() in ("history", "cau", "cầu", "ls"):
        chat_id = update.effective_chat.id
        hist_text = _build_history_text(chat_id)
        sent = await update.message.reply_text(hist_text, parse_mode="Markdown")
        asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 30))
        return

    # /tx all → cược tất cả coin hiện có
    if args and args[0].lower() == "all":
        current = get_coin(uid)
        if current <= 0:
            s = await update.message.reply_text(
                "❌ Bạn không có coin nào để cược!",
                parse_mode="Markdown"
            )
            asyncio.create_task(_auto_delete(context.bot, s.chat_id, s.message_id, 5))
            return
        context.args = [str(current)]

    await taixiu_command(update, context)

async def taixiu_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global TAIXIU_ENABLED
    if not update.message:
        return
    uid  = update.effective_user.id
    name = update.effective_user.first_name or "bạn"

    args = context.args

    # ── Admin: bật/tắt tính năng ──────────────────────────
    if args and args[0].lower() in ("on", "off"):
        if uid != ADMIN_ID:
            await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
            return
        TAIXIU_ENABLED = args[0].lower() == "on"
        status = "✅ bật" if TAIXIU_ENABLED else "❌ tắt"
        await update.message.reply_text(
            f"🎲 Tính năng tài xỉu đã *{status}*.",
            parse_mode="Markdown"
        )
        return

    # ── Kiểm tra tính năng có bật không ───────────────────
    if not TAIXIU_ENABLED:
        s1 = await update.message.reply_text("❌ Tính năng tài xỉu hiện đang bị tắt.")
        asyncio.create_task(_auto_delete(context.bot, s1.chat_id, s1.message_id, 5))
        return

    if not args:
        s2 = await update.message.reply_text(
            "🎲 *Cách dùng:* `/taixiu <số coin>`\n"
            "Ví dụ: `/taixiu 5`\n\n"
            f"💰 Coin hiện tại: *{get_coin(uid)}*",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s2.chat_id, s2.message_id, 5))
        return

    try:
        amount = int(args[0])
    except ValueError:
        s3 = await update.message.reply_text("❌ Số coin phải là số nguyên!", parse_mode="Markdown")
        asyncio.create_task(_auto_delete(context.bot, s3.chat_id, s3.message_id, 5))
        return

    if amount <= 0:
        s4 = await update.message.reply_text("❌ Đặt cược ít nhất 1 coin!", parse_mode="Markdown")
        asyncio.create_task(_auto_delete(context.bot, s4.chat_id, s4.message_id, 5))
        return

    current = get_coin(uid)
    if amount > current:
        s5 = await update.message.reply_text(
            f"❌ Không đủ coin!\n💰 Coin hiện tại: *{current}*",
            parse_mode="Markdown"
        )
        asyncio.create_task(_auto_delete(context.bot, s5.chat_id, s5.message_id, 5))
        return

    # Nếu đang có phiên → không cho tạo mới, cho tuỳ chọn huỷ
    if uid in TAIXIU_GAMES:
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("🗑️ Huỷ phiên (mất coin)", callback_data=f"tx_cancel_{uid}_yes")]
        ])
        s6 = await update.message.reply_text(
            "⚠️ Bạn đang có một phiên tài xỉu chưa kết thúc!\n"
            "Bấm *Huỷ phiên* để bỏ (mất coin đã đặt) và chơi lại.",
            parse_mode="Markdown",
            reply_markup=keyboard
        )
        asyncio.create_task(_auto_delete(context.bot, s6.chat_id, s6.message_id, 15))
        return

    # Bước 1: trừ coin ngay khi đặt cược
    set_coin(uid, current - amount)

    # Bước 1: chọn tài hoặc xỉu
    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🔴 Tài (11-18)", callback_data=f"tx_choice_{uid}_tai"),
            InlineKeyboardButton("🔵 Xỉu (3-10)",  callback_data=f"tx_choice_{uid}_xiu"),
        ],
        [
            InlineKeyboardButton("📊 Xem Cầu", callback_data=f"tx_history_{uid}_view"),
        ]
    ])
    msg = await update.message.reply_text(
        f"🎲 *{name}* đặt cược *{amount} coin*\n\n"
        "Chọn *Tài* hay *Xỉu*?",
        parse_mode="Markdown",
        reply_markup=keyboard
    )
    TAIXIU_GAMES[uid] = {
        "amount":   amount,
        "choice":   None,
        "dice":     [random.randint(1,6) for _ in range(3)],
        "revealed": [False, False, False],
        "msg_id":   msg.message_id,
        "chat_id":  msg.chat_id,
        "step":     "choose_side",   # choose_side → choose_bowl → done
        "expiry_task": None,
    }
    # Lên lịch tự huỷ sau SESSION_EXPIRY giây
    task = asyncio.create_task(_session_expiry_task(uid, context.bot))
    TAIXIU_GAMES[uid]["expiry_task"] = task

# ─── Callback handler tài xỉu ───────────────────────────────
async def taixiu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    data = query.data          # e.g. "tx_choice_123_tai"
    parts = data.split("_")
    # parts[0]="tx", parts[1]=action, parts[2]=uid, parts[3]=value

    if len(parts) < 4:
        return

    action = parts[1]          # choice / bowl / dice
    uid    = int(parts[2])
    value  = parts[3]          # tai/xiu or mo/up or 0/1/2

    # Chỉ người chơi mới được bấm (trừ xem cầu — ai cũng xem được)
    if action != "history" and query.from_user.id != uid:
        await query.answer("❌ Đây không phải game của bạn!", show_alert=True)
        return

    game = TAIXIU_GAMES.get(uid)
    if not game:
        await query.answer("⏰ Phiên đã hết hạn hoặc kết thúc rồi. Dùng /tx để chơi lại!", show_alert=True)
        try:
            await query.delete_message()
        except Exception:
            pass
        return

    name = query.from_user.first_name or "bạn"

    # ── Mỗi lần bấm: reset đồng hồ 10s ───────────────────
    if game.get("expiry_task"):
        game["expiry_task"].cancel()
    new_task = asyncio.create_task(_session_expiry_task(uid, context.bot))
    game["expiry_task"] = new_task

    # ── Xem cầu (bất kỳ ai trong nhóm có thể xem) ────────
    if action == "history":
        chat_id = query.message.chat_id
        hist_text = _build_history_text(chat_id)
        await query.answer()
        try:
            sent = await context.bot.send_message(
                chat_id=chat_id,
                text=hist_text,
                parse_mode="Markdown"
            )
            asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 30))
        except Exception as e:
            await query.answer(f"Lỗi: {e}", show_alert=True)
        return

    # ── Huỷ phiên thủ công ────────────────────────────────
    if action == "cancel":
        game2 = TAIXIU_GAMES.pop(uid, None)
        if game2:
            if game2.get("expiry_task"):
                game2["expiry_task"].cancel()
            try:
                await context.bot.delete_message(chat_id=game2["chat_id"], message_id=game2["msg_id"])
            except Exception:
                pass
        await query.edit_message_text("🗑️ Đã huỷ phiên. Dùng /tx để chơi lại.")
        return

    # ── Bước 1: chọn tài/xỉu ──────────────────────────────
    if action == "choice" and game["step"] == "choose_side":
        game["choice"] = value   # "tai" hoặc "xiu"
        label = "🔴 Tài" if value == "tai" else "🔵 Xỉu"

        keyboard = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("🫙 Mở bát (xem ngay)",   callback_data=f"tx_bowl_{uid}_mo"),
                InlineKeyboardButton("🪣 Úp bát (mở từng cái)", callback_data=f"tx_bowl_{uid}_up"),
            ]
        ])
        await query.edit_message_text(
            f"🎲 *{name}* chọn *{label}* — cược *{game['amount']} coin*\n\n"
            "Bây giờ chọn cách tung xúc xắc:",
            parse_mode="Markdown",
            reply_markup=keyboard
        )
        game["step"] = "choose_bowl"

    # ── Bước 2: chọn mở bát hoặc úp bát ──────────────────
    elif action == "bowl" and game["step"] == "choose_bowl":
        d = game["dice"]
        total = sum(d)
        result_tx = "xiu" if total <= 10 else "tai"
        choice_label = "🔴 Tài" if game["choice"] == "tai" else "🔵 Xỉu"

        if value == "mo":
            # Mở bát: tung xúc xắc Telegram thật (animated dice sticker)
            chat_id = game["chat_id"]
            await query.edit_message_text(
                f"🎲 *{name}* đặt *{choice_label}* — cược *{game['amount']} coin*\n\n"
                "🫙 Đang mở bát...",
                parse_mode="Markdown"
            )
            # Gửi 3 xúc xắc Telegram animated, lấy value thật
            m1 = await context.bot.send_dice(chat_id=chat_id, emoji="🎲")
            m2 = await context.bot.send_dice(chat_id=chat_id, emoji="🎲")
            m3 = await context.bot.send_dice(chat_id=chat_id, emoji="🎲")
            d  = [m1.dice.value, m2.dice.value, m3.dice.value]
            total     = sum(d)
            result_tx = "xiu" if total <= 10 else "tai"
            win = (result_tx == game["choice"])
            game["dice"] = d
            _save_history(chat_id, name, game, d, total, result_tx, win)
            _apply_result(uid, game, win)
            result_msg = _build_result_msg(name, game, d, total, result_tx, win, uid)
            # Chờ animation xong (~4s) rồi xoá 3 dice + tin "Đang mở bát", hiện kết quả
            await asyncio.sleep(4)
            for m in (m1, m2, m3):
                try:
                    await context.bot.delete_message(chat_id=chat_id, message_id=m.message_id)
                except Exception:
                    pass
            sent = await context.bot.send_message(
                chat_id=chat_id,
                text=f"🫙 *Kết quả!*\n\n{result_msg}",
                parse_mode="Markdown"
            )
            # Xoá tin "Đang mở bát"
            try:
                await query.delete_message()
            except Exception:
                pass
            asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 10))
            _end_game(uid)

        else:
            # Úp bát: tạo 3 nút bấm ẩn
            game["step"] = "up_bat"
            await query.edit_message_text(
                _build_upbat_text(name, game, d),
                parse_mode="Markdown",
                reply_markup=_build_upbat_keyboard(uid, game)
            )

    # ── Bước 3: úp bát — bấm từng xúc xắc ───────────────
    elif action == "dice" and game.get("step") == "up_bat":
        idx = int(value)
        if game["revealed"][idx]:
            return   # đã mở rồi

        game["revealed"][idx] = True
        d = game["dice"]

        all_revealed = all(game["revealed"])

        if all_revealed:
            total = sum(d)
            result_tx = "xiu" if total <= 10 else "tai"
            win = (result_tx == game["choice"])
            _save_history(query.message.chat_id, name, game, d, total, result_tx, win)
            _apply_result(uid, game, win)
            dice_str = " ".join(DICE_FACES[v-1] for v in d)
            result_msg = _build_result_msg(name, game, d, total, result_tx, win, uid)
            await query.edit_message_text(
                f"🪣 *Mở xong cả bát!*\n\n{dice_str}\n\n{result_msg}",
                parse_mode="Markdown"
            )
            asyncio.create_task(_auto_delete(context.bot, query.message.chat_id, query.message.message_id, 10))
            _end_game(uid)
        else:
            # Cập nhật bảng với xúc xắc vừa mở
            await query.edit_message_text(
                _build_upbat_text(name, game, d),
                parse_mode="Markdown",
                reply_markup=_build_upbat_keyboard(uid, game)
            )

# ─── Helper functions ─────────────────────────────────────────
def _save_history(chat_id: int, name: str, game: dict, d: list, total: int, result_tx: str, win: bool):
    """Lưu kết quả phiên vào TAIXIU_HISTORY."""
    record = {
        "name":   name,
        "amount": game["amount"],
        "dice":   d[:],
        "total":  total,
        "result": result_tx,   # "tai" | "xiu"
        "choice": game["choice"],
        "win":    win,
        "time":   datetime.now().strftime("%H:%M"),
    }
    if chat_id not in TAIXIU_HISTORY:
        TAIXIU_HISTORY[chat_id] = []
    TAIXIU_HISTORY[chat_id].append(record)
    # Giữ tối đa MAX_HISTORY phiên
    if len(TAIXIU_HISTORY[chat_id]) > MAX_HISTORY:
        TAIXIU_HISTORY[chat_id] = TAIXIU_HISTORY[chat_id][-MAX_HISTORY:]


def _build_history_text(chat_id: int) -> str:
    """Tạo chuỗi lịch sử cầu đẹp."""
    history = TAIXIU_HISTORY.get(chat_id, [])
    if not history:
        return "📭 Chưa có phiên nào trong nhóm này."

    lines = ["📊 *Cầu Tài Xỉu (20 phiên gần nhất)*\n"]
    # Dòng cầu trực quan — tài = 🔴, xỉu = 🔵
    streak_row = ""
    for r in history:
        streak_row += ("🔴" if r["result"] == "tai" else "🔵")
    lines.append(streak_row + "\n")

    # Thống kê nhanh
    total_tai = sum(1 for r in history if r["result"] == "tai")
    total_xiu = len(history) - total_tai
    lines.append(f"🔴 Tài: *{total_tai}* lần  |  🔵 Xỉu: *{total_xiu}* lần\n")

    # Cầu liên tiếp hiện tại
    if history:
        last = history[-1]["result"]
        streak = 0
        for r in reversed(history):
            if r["result"] == last:
                streak += 1
            else:
                break
        streak_label = "🔴 Tài" if last == "tai" else "🔵 Xỉu"
        lines.append(f"🔥 Cầu hiện tại: *{streak_label} × {streak}*\n")

    lines.append("─────────────────")
    # Chi tiết từng phiên (5 phiên gần nhất)
    lines.append("🕐 *5 phiên gần nhất:*")
    for r in history[-5:]:
        dice_str = " ".join(DICE_FACES[v-1] for v in r["dice"])
        res_lbl  = "🔴Tài" if r["result"] == "tai" else "🔵Xỉu"
        cho_lbl  = "🔴Tài" if r["choice"] == "tai" else "🔵Xỉu"
        win_lbl  = "✅" if r["win"] else "❌"
        lines.append(
            f"{win_lbl} *{r['name']}* [{r['time']}] cược {cho_lbl} → {res_lbl} "
            f"({dice_str} = {r['total']})"
        )

    return "\n".join(lines)


def _end_game(uid: int):
    """Pop game và cancel expiry task."""
    game = TAIXIU_GAMES.pop(uid, None)
    if game and game.get("expiry_task"):
        game["expiry_task"].cancel()

def _apply_result(uid: int, game: dict, win: bool):
    if win:
        # Coin đã bị trừ lúc đặt cược → thắng thì cộng lại 2x
        cur = get_coin(uid)
        set_coin(uid, cur + game["amount"] * 2)

def _build_result_msg(name, game, d, total, result_tx, win, uid: int):
    result_label = "🔴 Tài" if result_tx == "tai"      else "🔵 Xỉu"
    choice_label = "🔴 Tài" if game["choice"] == "tai"  else "🔵 Xỉu"
    new_coin     = get_coin(uid)
    if win:
        outcome = f"✅ *Thắng!* +{game['amount']} coin 🎉"
    else:
        outcome = f"❌ *Thua!* -{game['amount']} coin 😢"
    return (
        f"🎯 Tổng: *{total}* → {result_label}\n"
        f"Bạn chọn: {choice_label}\n"
        f"{outcome}\n"
        f"💰 Coin còn lại: *{new_coin}*"
    )

def _build_upbat_text(name, game, d):
    choice_label = "🔴 Tài" if game["choice"] == "tai" else "🔵 Xỉu"
    parts = []
    for i, rev in enumerate(game["revealed"]):
        parts.append(DICE_FACES[d[i]-1] if rev else DICE_HIDDEN)
    dice_str = " ".join(parts)
    return (
        f"🪣 *{name}* — chọn {choice_label} — cược *{game['amount']} coin*\n\n"
        f"{dice_str}\n\n"
        "Bấm vào từng xúc xắc để lật mở:"
    )

def _build_upbat_keyboard(uid: int, game: dict):
    buttons = []
    for i, rev in enumerate(game["revealed"]):
        if rev:
            label = DICE_FACES[game["dice"][i]-1]
        else:
            label = DICE_HIDDEN
        buttons.append(InlineKeyboardButton(label, callback_data=f"tx_dice_{uid}_{i}"))
    return InlineKeyboardMarkup([buttons])


# ─── /lamviec ────────────────────────────────────────────────
# Lưu thời điểm bắt đầu làm việc {user_id: datetime}
LAMVIEC_START: dict = {}

async def lamviec_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    uid  = update.effective_user.id
    name = update.effective_user.first_name or "bạn"
    now  = datetime.utcnow()
    tz_vn = timedelta(hours=7)

    # Đang có phiên làm việc → kiểm tra xem đã đủ 1 tiếng chưa
    if uid in LAMVIEC_START:
        elapsed = now - LAMVIEC_START[uid]
        total_seconds = int(elapsed.total_seconds())

        if total_seconds >= 3600:
            # Đủ 1 tiếng → thưởng coin
            del LAMVIEC_START[uid]
            earned = 10
            new_coin = get_coin(uid) + earned
            set_coin(uid, new_coin)
            minutes = total_seconds // 60
            await update.message.reply_text(
                f"✅ *{name}* đã làm việc *{minutes} phút*!\n"
                f"💰 Nhận được *+{earned} coin*.\n"
                f"💼 Coin hiện tại: *{new_coin}*",
                parse_mode="Markdown"
            )
        else:
            # Chưa đủ → báo còn bao lâu nữa
            remaining = 3600 - total_seconds
            m = remaining // 60
            s = remaining % 60
            done_at = (LAMVIEC_START[uid] + timedelta(hours=1) + tz_vn).strftime("%H:%M:%S")
            await update.message.reply_text(
                f"⏳ *{name}* đang làm việc...\n"
                f"🕐 Còn *{m} phút {s} giây* nữa để nhận coin.\n"
                f"✅ Hoàn thành lúc: *{done_at}*",
                parse_mode="Markdown"
            )
        return

    # Chưa có phiên → bắt đầu
    tz_vn = timedelta(hours=7)
    now_vn = datetime.utcnow() + tz_vn
    LAMVIEC_START[uid] = datetime.utcnow()  # lưu UTC để tính elapsed chính xác
    done_at = (now_vn + timedelta(hours=1)).strftime("%H:%M:%S")

    activities = [
        "đang đi đánh lộn 🥊",
        "đang đi từ thiện 🫶",
        "đang bán thận 🫀",
        "đang thăm người yêu cũ 💔",
        "đang đi ỉa 🚽",
    ]
    activity = random.choice(activities)

    sent = await update.message.reply_text(
        f"💼 *{name}* bắt đầu làm việc!\n"
        f"👀 Thực ra là *{name}* {activity}\n\n"
        f"⏰ Làm đủ 1 tiếng để nhận *+10 coin*.\n"
        f"✅ Hoàn thành lúc: *{done_at}*\n\n"
        f"Dùng /lamviec lại sau 1 tiếng để nhận thưởng.",
        parse_mode="Markdown"
    )
    asyncio.create_task(_auto_delete(context.bot, sent.chat_id, sent.message_id, 10))


ALL_GROUP_ID = -1003948095853

async def in_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/in - Admin thêm người vào danh sách tag /all"""
    if not update.message:
        return

    if update.effective_user.id != ADMIN_ID:
        await update.message.reply_text("❌ Chỉ admin mới dùng được lệnh này!")
        return

    chat = update.effective_chat
    reply = update.message.reply_to_message

    target_user = None
    if reply:
        target_user = reply.from_user
    elif context.args:
        # /in @username hoặc /in user_id
        arg = context.args[0].lstrip("@")
        try:
            uid = int(arg)
            member = await context.bot.get_chat_member(chat.id, uid)
            target_user = member.user
        except Exception:
            await update.message.reply_text(
                "❌ Không tìm được người dùng đó.\nHãy reply tin nhắn của họ hoặc dùng ID số."
            )
            return
    else:
        await update.message.reply_text(
            "📝 Cách dùng:\n"
            "• Reply tin nhắn của người muốn thêm + `/in`\n"
            "• `/in <user_id>`",
            parse_mode="Markdown",
        )
        return

    if target_user.is_bot:
        await update.message.reply_text("❌ Không thể thêm bot vào danh sách!")
        return

    chat_id = chat.id
    if chat_id not in MEMBER_CACHE:
        MEMBER_CACHE[chat_id] = {}

    MEMBER_CACHE[chat_id][target_user.id] = {
        "name": target_user.first_name or str(target_user.id),
        "username": target_user.username or "",
    }

    name = f"@{target_user.username}" if target_user.username else target_user.first_name
    total = len(MEMBER_CACHE[chat_id])
    await update.message.reply_text(
        f"✅ Đã thêm *{name}* vào danh sách tag.\n"
        f"📋 Tổng danh sách: *{total}* người",
        parse_mode="Markdown",
    )


