async def all_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Tag tất cả thành viên trong nhóm bằng /all hoặc @all"""
    if not update.message:
        return

    chat = update.effective_chat
    if chat.id != ALL_GROUP_ID:
        await update.message.reply_text("❌ Lệnh này chỉ dùng được trong nhóm được chỉ định!")
        return

    if chat.type not in ("group", "supergroup"):
        await update.message.reply_text("❌ Lệnh này chỉ dùng trong nhóm!")
        return

    # Lấy danh sách thành viên từ admin + cache tin nhắn
    try:
        members = []
        seen_ids = set()

        # Lấy từ cache thành viên đã được thêm bằng /in
        for uid, uinfo in list(MEMBER_CACHE.get(chat.id, {}).items()):
            if uid in seen_ids:
                continue
            seen_ids.add(uid)
            if uinfo.get("username"):
                members.append(f"@{uinfo['username']}")
            else:
                name = uinfo.get("name") or str(uid)
                members.append(f'<a href="tg://user?id={uid}">{name}</a>')

        if not members:
            await update.message.reply_text(
                "❌ Chưa có dữ liệu thành viên!\n"
                "Bot sẽ tự động thu thập khi mọi người nhắn tin trong nhóm."
            )
            return

        # Lấy nội dung kèm theo lệnh (nếu có)
        args = context.args
        caption = " ".join(args) if args else "📢 Thông báo!"

        # Chia nhỏ nếu danh sách quá dài (giới hạn Telegram ~4096 ký tự)
        chunk = []
        chunks = []
        length = len(caption) + 2
        for mention in members:
            if length + len(mention) + 1 > 4000:
                chunks.append(chunk)
                chunk = []
                length = 0
            chunk.append(mention)
            length += len(mention) + 1
        if chunk:
            chunks.append(chunk)

        # Gửi từng chunk bằng send_message (không reply, để Telegram notify đúng)
        for i, ch in enumerate(chunks):
            text = (caption + "\n" if i == 0 else "") + " ".join(ch)
            await context.bot.send_message(
                chat_id=chat.id,
                text=text,
                parse_mode="HTML",
            )

    except Exception as e:
        await update.message.reply_text(f"❌ Lỗi khi lấy danh sách thành viên: {e}")


