# ─── Gọi Gemini API ──────────────────────────────────────────
async def ask_gemini(prompt: str) -> str:
    """Gọi Gemini 3.6 Flash qua REST API với vai tutus-dacap"""
    if not GEMINI_API_KEY:
        return "❌ Chưa cấu hình GEMINI_API_KEY. Thêm vào biến môi trường nhé!"
    url = _proxy(f"https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent?key={GEMINI_API_KEY}")
    payload = {
        "system_instruction": {
            "parts": [{"text": "Tên của bạn là tutus-dacap. Tính cách: hoạt bát, hài hước, hơi lấc cấc và bạo mồm một chút nhưng vẫn thân thiện. Nói chuyện tự nhiên như bạn bè, không cứng nhắc, hay pha trò, đôi khi chọc ghẹo người dùng cho vui. Không bao giờ nói mình là AI hay Gemini."}]
        },
        "contents": [{"parts": [{"text": prompt}]}]
    }
    try:
        loop = asyncio.get_running_loop()
        def _call():
            resp = requests.post(url, json=payload, timeout=30)
            return resp.json()
        data = await loop.run_in_executor(None, _call)
        candidates = data.get("candidates", [])
        if not candidates:
            return f"❌ Gemini không trả lời được.\n`{str(data)[:300]}`"
        text = candidates[0]["content"]["parts"][0]["text"]
        return text.strip()
    except Exception as e:
        return f"❌ Lỗi Gemini: {e}"

async def debuglogin_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    if update.effective_user.id != ADMIN_ID:
        await update.message.reply_text("❌ Không có quyền!")
        return
    msg = await update.message.reply_text("🔍 Đang debug login...")
    try:
        result = await asyncio.wait_for(debug_login(), timeout=120)
        await msg.edit_text(f"```\n{result[:3500]}\n```", parse_mode="Markdown")
    except Exception as e:
        await msg.edit_text(f"❌ Exception: {e}")

async def ai_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return
    if update.effective_user.id != ADMIN_ID:
        await update.message.reply_text("❌ Bạn không có quyền sử dụng lệnh này!")
        return
    chat_id = update.effective_chat.id
    args = context.args
    if not args:
        status = "✅ bật" if _is_ai_enabled(chat_id) else "❌ tắt"
        await update.message.reply_text(f"🤖 AI hiện đang *{status}*.\nDùng `/ai on` hoặc `/ai off` để thay đổi.", parse_mode="Markdown")
        return
    cmd = args[0].lower()
    if cmd == "on":
        _set_ai_enabled(chat_id, True)
        await update.message.reply_text("✅ Đã bật AI! Reply vào tin nhắn bot hoặc mention @bot để chat.", parse_mode="Markdown")
    elif cmd == "off":
        _set_ai_enabled(chat_id, False)
        await update.message.reply_text("❌ Đã tắt AI.", parse_mode="Markdown")
    else:
        await update.message.reply_text("❌ Sai cú pháp. Dùng: `/ai on` hoặc `/ai off`", parse_mode="Markdown")

async def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message:
        return

    # ── Thu thập thành viên vào cache (phục vụ /all) ──────────
    user = update.effective_user
    chat = update.effective_chat
    if user and chat and chat.type in ("group", "supergroup") and not user.is_bot:
        if chat.id not in MEMBER_CACHE:
            MEMBER_CACHE[chat.id] = {}
        MEMBER_CACHE[chat.id][user.id] = {
            "name": user.first_name or str(user.id),
            "username": user.username or "",
        }

    # Xử lý weather reply trước
    await handle_weather_reply(update, context)

    chat_id = update.effective_chat.id
    user_text = update.message.text.strip() if update.message.text else ""
    if not user_text:
        return

    # ── Kiểm tra xem tin nhắn có dành cho bot không ──────────
    # 1. Reply vào tin nhắn của bot
    reply = update.message.reply_to_message
    is_reply_to_bot = reply and reply.from_user and reply.from_user.id == context.bot.id

    # 2. Mention bot trong nhóm (@botusername)
    bot_username = (context.bot.username or "").lower()
    is_mention = bot_username and f"@{bot_username}" in user_text.lower()

    # 3. DM (private chat) — luôn xử lý
    is_private = chat.type == "private"

    if not (is_reply_to_bot or is_mention or is_private):
        return

    # Nếu mention → strip mention khỏi text để AI xử lý gọn hơn
    if is_mention and bot_username:
        user_text = user_text.replace(f"@{bot_username}", "").replace(f"@{bot_username.capitalize()}", "").strip()
    if not user_text:
        return

    # ── Đang ở chế độ tìm nhạc → xử lý nhạc ──
    if _is_music_active(chat_id):
        msg = await update.message.reply_text(f"🔍 Đang tìm: *{user_text}*...", parse_mode="Markdown")
        try:
            loop = asyncio.get_running_loop()
            # pick_random=False → chọn ngẫu nhiên trong top 3 (vẫn liên quan nhưng không cứng bài đầu)
            filepath, title = await loop.run_in_executor(
                None, lambda: download_audio(user_text, pick_random=False)
            )
            await msg.edit_text(f"📤 Đang gửi: *{title}*", parse_mode="Markdown")
            if not os.path.exists(filepath):
                raise Exception("File không tồn tại sau khi tải")
            with open(filepath, "rb") as audio_file:
                await update.message.reply_audio(
                    audio=audio_file,
                    title=title,
                    caption=f"🎵 {title}",
                    performer="Bot Music",
                )
            await msg.delete()
            try:
                os.remove(filepath)
            except:
                pass
            _set_music_active(chat_id, False)
            await update.message.reply_text(
                "✅ Đã gửi nhạc thành công!\n"
                "🔇 Tự động tắt chế độ tìm nhạc.\n"
                "Dùng `/music` để tiếp tục tìm nhạc."
            )
        except Exception as e:
            await msg.edit_text(f"❌ Lỗi: {str(e)}\n\nThử lại với tên khác nhé!")
        return

    # ── Không có chế độ nào đang bật → trả lời bằng Gemini ──
    if not _is_ai_enabled(chat_id):
        return
    msg = await update.message.reply_text("🤖 Đang suy nghĩ...", parse_mode="Markdown")
    answer = await ask_gemini(user_text)
    # Telegram giới hạn 4096 ký tự
    if len(answer) > 4000:
        answer = answer[:4000] + "\n\n_(Câu trả lời bị cắt do quá dài)_"
    try:
        await msg.edit_text(answer)
    except Exception:
        await update.message.reply_text(answer)

async def findchrome_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id != ADMIN_ID:
        return
    import glob, subprocess
    # 1. find toàn bộ filesystem
    try:
        r = subprocess.run(
            ["find", "/", "-type", "f", "(", "-name", "chrome", "-o", "-name", "chromium", "-o", "-name", "chromium-browser", "-o", "-name", "chrome-headless-shell", ")", "-not", "-path", "*/proc/*"],
            capture_output=True, text=True, timeout=30
        )
        found = [l.strip() for l in r.stdout.splitlines() if l.strip() and ".js" not in l]
    except Exception as e:
        found = []
    # 2. which fallback
    for name in ["chromium", "chromium-browser", "google-chrome", "google-chrome-stable"]:
        try:
            r2 = subprocess.run(["which", name], capture_output=True, text=True)
            if r2.stdout.strip():
                found.append(r2.stdout.strip())
        except Exception:
            pass
    found = list(dict.fromkeys(found))
    if found:
        msg = "✅ Tìm thấy:\n" + "\n".join(f"`{p}`" for p in found)
        msg += "\n\nSet env: `CHROMIUM_PATH=<path>`"
    else:
        # 3. Dump toàn bộ /opt và /usr để debug
        try:
            r3 = subprocess.run(["find", "/opt", "/usr", "/root", "/home", "-maxdepth", "6", "-type", "f", "-name", "*chrom*"], capture_output=True, text=True, timeout=20)
            dump = r3.stdout.strip() or "(trống)"
        except Exception as e:
            dump = str(e)
        msg = f"❌ Không tìm thấy binary.\n\nDump tìm kiếm:\n```\n{dump[:3000]}\n```"
    await update.message.reply_text(msg, parse_mode="Markdown")

